"""Orchestratore dei cinque casi d'uso di RF-39, identici su ogni superficie.

Dipende solo dalle porte: repository, HofJ e pagamenti sono iniettati. `now` e `new_id` sono
iniettabili per i test. Ogni risposta porta `say` (RF-42) e mai più di un prodotto (RF-10).
"""
import functools
import logging
import time
import uuid
from dataclasses import replace
from datetime import datetime, timezone
from decimal import Decimal
    def __init__(self):
        self._items: Dict[str, Product] = {}

    def upsert_many(self, products: Iterable[Product]) -> None:
        for p in products:
            self._items[p.id] = p

    def count(self) -> int:
        return len(self._items)

    def list_all(self) -> List[Product]:
        return list(self._items.values())

    def get(self, product_id: str) -> Optional[Product]:
        return self._items.get(product_id)

    def last_fetched_at(self) -> Optional[datetime]:
        return max((p.fetched_at for p in self._items.values()), default=None)

    def set_bookable(self, product_id: str, bookable: bool, checked_at: datetime) -> None:
        p = self._items.get(product_id)

